    EXECUTE $q$SELECT cron.schedule('app_purge_admin_auth_attempts', '17 3 * * *',
      $j$DELETE FROM app.admin_auth_attempts WHERE attempted_at < now() - interval '30 days'$j$)$q$;
  END IF;
