-- ==================== 011_personality_matching.sql
-- 011: personality matching (rule version r2-personality, spec docs/specs/2026-10-30-personality-matching-design.md).
-- * matching_runs accepts the algorithm personality_v1.
-- * event_tables.match_themes keeps the "what you share" line computed at publish ([{q, o, ar, en}]); it is cleared
--   when an admin moves a member, because it no longer describes the table.
-- * matching_input() also returns, per booking, every answer as {question_key: [option_key, ...]}, and the option
--   keys of the published questionnaire, which the engine checks before it runs.
-- Re-running this file is safe.
SET search_path = app, pg_temp;

ALTER TABLE matching_runs DROP CONSTRAINT IF EXISTS matching_runs_algorithm_check;
ALTER TABLE matching_runs ADD CONSTRAINT matching_runs_algorithm_check
  CHECK (algorithm IN ('baseline_random', 'interest_opt_v1', 'personality_v1'));

ALTER TABLE event_tables ADD COLUMN IF NOT EXISTS match_themes jsonb;
COMMENT ON COLUMN event_tables.match_themes IS 'Shared themes shown to members after reveal ([{q, o, ar, en}]); NULL = none or cleared after a manual move';

CREATE OR REPLACE FUNCTION matching_input(p_session uuid) RETURNS json LANGUAGE sql STABLE AS $$
  SELECT json_build_object(
    'session_id', s.id,
    'questionnaire_version_id', (SELECT id FROM questionnaire_versions WHERE status = 'published'),
    'questionnaire', COALESCE((
      SELECT json_object_agg(x.key, x.opts) FROM (
        SELECT q.key, json_agg(o.key ORDER BY o.key) AS opts
          FROM questions q JOIN question_options o ON o.question_id = q.id
         WHERE q.questionnaire_version_id = (SELECT id FROM questionnaire_versions WHERE status = 'published')
         GROUP BY q.key) x), '{}'::json),
    'bookings', COALESCE((
      SELECT json_agg(json_build_object(
        'booking_id', b.id, 'user_id', b.user_id, 'session_id', b.session_id, 'status', b.status,
        'conversation_language', b.conversation_language, 'budget_tier_rank', bt.rank,
        'q05_topics', (SELECT json_agg(o.key ORDER BY o.key) FROM answers a
                         JOIN questions q ON q.id = a.question_id AND q.key = 'Q05'
                         JOIN question_options o ON o.id = a.option_id
                        WHERE a.response_id = b.questionnaire_response_id),
        'answers', (SELECT json_object_agg(x.key, x.opts) FROM (
                      SELECT q.key, json_agg(o.key ORDER BY o.key) AS opts FROM answers a
                        JOIN questions q ON q.id = a.question_id
                        JOIN question_options o ON o.id = a.option_id
                       WHERE a.response_id = b.questionnaire_response_id
                       GROUP BY q.key) x),
        'consents_current', (SELECT count(*) = 3 FROM current_consents c
                              WHERE c.user_id = b.user_id AND c.granted
                                AND c.consent_type IN ('terms','conduct','privacy_notice')),
        'age_attested', u.age_eligibility_confirmed_at IS NOT NULL,
        'account_active', u.status = 'active') ORDER BY b.id)
      FROM bookings b JOIN users u ON u.id = b.user_id JOIN budget_tiers bt ON bt.id = b.budget_tier_id
      WHERE b.session_id = s.id AND b.status = 'paid_awaiting_group'), '[]'::json),
    'blocks', COALESCE((SELECT json_agg(json_build_array(ub.blocker_user_id, ub.blocked_user_id))
                          FROM user_blocks ub), '[]'::json),
    'venues', COALESCE((SELECT json_agg(json_build_object('venue_id', v.id, 'tier_rank', bt.rank,
                                 'capacity', LEAST(v.seats_per_table_max, 6), 'tables_available', v.total_bookable_tables)
                                 ORDER BY v.id)
                          FROM venues v JOIN budget_tiers bt ON bt.id = v.budget_tier_id
                         WHERE v.city_id = s.city_id AND v.is_active AND s.experience = ANY (v.supported_experiences)),
                       '[]'::json))
  FROM event_sessions s WHERE s.id = p_session;
$$;
-- CREATE OR REPLACE drops function settings; keep the pin from 002 (names resolve in app whatever the caller's path)
ALTER FUNCTION matching_input(uuid) SET search_path = app, pg_temp;

-- ==================== 012_promo_codes.sql
-- 012: promo codes (HerZone). Created by an owner in the admin dashboard: a percentage off, an optional expiry and an
-- optional usage limit. Subscriptions are display-only for now, so a member can only check a code and see the
-- discounted price; nothing is redeemed and `uses` stays 0 until purchases exist. Checks are rate-limited per member
-- (promo_code_checks) so codes cannot be guessed. Re-running this file is safe.
SET search_path = app, pg_temp;

CREATE TABLE IF NOT EXISTS promo_codes (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code        varchar(24) NOT NULL UNIQUE CHECK (code ~ '^[A-Z0-9]{3,24}$'),
  percent_off smallint NOT NULL CHECK (percent_off BETWEEN 1 AND 100),
  expires_at  timestamptz,
  max_uses    integer CHECK (max_uses IS NULL OR max_uses > 0),
  uses        integer NOT NULL DEFAULT 0 CHECK (uses >= 0),
  is_active   boolean NOT NULL DEFAULT true,
  created_by  uuid REFERENCES admin_users(id),
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS promo_codes_created_by_fk_idx ON promo_codes (created_by);

CREATE TABLE IF NOT EXISTS promo_code_checks (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id    uuid NOT NULL REFERENCES users(id),
  at         timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS promo_code_checks_user_at_idx ON promo_code_checks (user_id, at);

-- same protection as every app table (002, 007): RLS with an explicit deny-all policy, no client-role privileges
DO $$
DECLARE t text; r text;
BEGIN
  FOREACH t IN ARRAY ARRAY['promo_codes','promo_code_checks'] LOOP
    EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('DROP POLICY IF EXISTS deny_all ON app.%I', t);
    EXECUTE format('CREATE POLICY deny_all ON app.%I AS RESTRICTIVE FOR ALL TO PUBLIC USING (false) WITH CHECK (false)', t);
    FOREACH r IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
      IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
        EXECUTE format('REVOKE ALL ON app.%I FROM %I', t, r);
      END IF;
    END LOOP;
  END LOOP;
END $$;

-- ==================== 013_push_notifications.sql
-- 013: phone notifications (Web Push). push_subscriptions holds one row per member device (the browser's push
-- endpoint and its public keys; no phone number, no message content). The dispatcher (POST /api/internal/push:dispatch)
-- sends queued push-channel notifications; pg_cron calls it every minute through pg_net with the token in
-- push_dispatch_token, which only the database and the API read. Where pg_cron / pg_net or the dispatch URL are not
-- available (local PostgreSQL) the schedule is skipped. Re-running this file is safe.
SET search_path = app, pg_temp;

CREATE TABLE IF NOT EXISTS push_subscriptions (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id         uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  endpoint        varchar(1000) NOT NULL UNIQUE,
  p256dh          varchar(100) NOT NULL,
  auth            varchar(40) NOT NULL,
  failures        integer NOT NULL DEFAULT 0,
  last_error      varchar(200),
  last_success_at timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS push_subscriptions_user_id_fk_idx ON push_subscriptions (user_id);

CREATE TABLE IF NOT EXISTS push_dispatch_token (
  id    smallint PRIMARY KEY CHECK (id = 1),
  token text NOT NULL
);
-- two random UUIDs (v4, from a secure generator): 244 random bits
INSERT INTO push_dispatch_token (id, token)
VALUES (1, replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''))
ON CONFLICT (id) DO NOTHING;

INSERT INTO app_config (key, value, description) VALUES
  ('PUSH_DISPATCH_URL', '', 'Full URL of POST /api/internal/push:dispatch that pg_cron calls every minute; empty = no schedule')
ON CONFLICT (key) DO NOTHING;

-- same protection as every app table (002, 007): RLS with an explicit deny-all policy, no client-role privileges
DO $$
DECLARE t text; r text;
BEGIN
  FOREACH t IN ARRAY ARRAY['push_subscriptions','push_dispatch_token'] LOOP
    EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('DROP POLICY IF EXISTS deny_all ON app.%I', t);
    EXECUTE format('CREATE POLICY deny_all ON app.%I AS RESTRICTIVE FOR ALL TO PUBLIC USING (false) WITH CHECK (false)', t);
    FOREACH r IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
      IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
        EXECUTE format('REVOKE ALL ON app.%I FROM %I', t, r);
      END IF;
    END LOOP;
  END LOOP;
END $$;

-- The call pg_cron makes: posts to the configured URL with the token. Runs as the table owner (SECURITY DEFINER) so the
-- token never has to be granted to anyone; not callable by client roles.
CREATE OR REPLACE FUNCTION push_dispatch_tick() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = app, pg_temp AS $$
DECLARE u text; t text;
BEGIN
  SELECT value INTO u FROM app.app_config WHERE key = 'PUSH_DISPATCH_URL';
  SELECT token INTO t FROM app.push_dispatch_token WHERE id = 1;
  IF coalesce(u, '') = '' OR t IS NULL THEN RETURN; END IF;
  EXECUTE 'SELECT net.http_post(url := $1, body := ''{}''::jsonb, headers := jsonb_build_object(''content-type'', ''application/json'', ''x-dispatch-token'', $2), timeout_milliseconds := 20000)'
    USING u, t;
END $$;
REVOKE ALL ON FUNCTION push_dispatch_tick() FROM PUBLIC;
DO $$
DECLARE r text;
BEGIN
  FOREACH r IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN EXECUTE format('REVOKE ALL ON FUNCTION app.push_dispatch_tick() FROM %I', r); END IF;
  END LOOP;
END $$;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'pg_cron')
     OR NOT EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'pg_net') THEN
    RAISE NOTICE 'pg_cron or pg_net not available: push dispatch schedule skipped';
    RETURN;
  END IF;
  BEGIN
    CREATE EXTENSION IF NOT EXISTS pg_cron;
    CREATE EXTENSION IF NOT EXISTS pg_net;
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'pg_cron / pg_net could not be enabled here (%): push dispatch schedule skipped', SQLERRM;
    RETURN;
  END;
  EXECUTE $q$SELECT cron.schedule('app_push_dispatch', '* * * * *', 'SELECT app.push_dispatch_tick()')$q$;
END $$;

-- ==================== 014_account_deletion.sql
-- 014: finish account deletion, as the privacy notice promises: after a request there is a 14-day period in which the
-- member can change her mind (signing in again cancels the request), then her number, name and questionnaire answers
-- are removed. Bookings, payments, refunds and safety reports stay for the records the business must keep, linked
-- only to an anonymous account. The number is free to sign up again as a new member.
-- A daily pg_cron job runs it where pg_cron exists (see 004). Re-running this file is safe.
SET search_path = app, pg_temp;

ALTER TABLE users ADD COLUMN IF NOT EXISTS deletion_requested_at timestamptz;

-- The request time follows the status, so the API needs no change to record it.
CREATE OR REPLACE FUNCTION app.track_deletion_request() RETURNS trigger
LANGUAGE plpgsql SET search_path = app, pg_temp AS $$
BEGIN
  IF NEW.status = 'deletion_requested' AND OLD.status IS DISTINCT FROM 'deletion_requested' THEN
    NEW.deletion_requested_at := now();
  ELSIF NEW.status <> 'deletion_requested' AND NEW.status <> 'deleted' THEN
    NEW.deletion_requested_at := NULL;
  END IF;
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS users_track_deletion_request ON users;
CREATE TRIGGER users_track_deletion_request BEFORE UPDATE OF status ON users
  FOR EACH ROW EXECUTE FUNCTION app.track_deletion_request();

-- Requests made before this migration have no time: they start their 14 days now.
UPDATE users SET deletion_requested_at = now() WHERE status = 'deletion_requested' AND deletion_requested_at IS NULL;

-- Removes the personal data of every account whose request is older than the grace period. Returns how many.
CREATE OR REPLACE FUNCTION app.finalize_account_deletions(grace interval DEFAULT interval '14 days') RETURNS integer
LANGUAGE plpgsql SET search_path = app, pg_temp AS $$
DECLARE
  ids uuid[];
BEGIN
  SELECT coalesce(array_agg(id), '{}') INTO ids FROM (
    SELECT id FROM users WHERE status = 'deletion_requested' AND deletion_requested_at <= now() - grace FOR UPDATE
  ) due;
  IF cardinality(ids) = 0 THEN RETURN 0; END IF;

  -- questionnaire answers (the response rows stay, empty, because bookings point to them)
  DELETE FROM answers WHERE response_id IN (SELECT id FROM questionnaire_responses WHERE user_id = ANY (ids));
  DELETE FROM push_subscriptions WHERE user_id = ANY (ids);
  DELETE FROM notifications_outbox WHERE user_id = ANY (ids);
  UPDATE refresh_tokens SET revoked_at = now() WHERE subject_id = ANY (ids) AND revoked_at IS NULL;

  -- number and name gone; a random lookup value so the number can sign up again as someone new
  UPDATE users
     SET display_name = NULL,
         phone_e164_enc = '\x'::bytea,
         phone_lookup_hash = replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''),
         status = 'deleted',
         deleted_at = now()
   WHERE id = ANY (ids);
  RETURN cardinality(ids);
END $$;

REVOKE ALL ON FUNCTION app.finalize_account_deletions(interval) FROM PUBLIC;
REVOKE ALL ON FUNCTION app.track_deletion_request() FROM PUBLIC;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    EXECUTE $q$SELECT cron.schedule('app_finalize_account_deletions', '41 2 * * *',
      $j$SELECT app.finalize_account_deletions()$j$)$q$;
  END IF;
END $$;

-- ==================== 015_card_name_check.sql
-- 015: name on the card vs the registered first name (identity check, line one against a man booking as a woman).
-- On a successful payment the API compares the two (lib/namematch.js). The card name is stored encrypted, always
-- (owner's decision of 4 Nov, for safety). A mismatch, or a member with no registered name, opens an identity review:
-- the booking stays paid but the venue, table code and tablemates are not shown to her until an admin approves.
-- A rejection is recorded as a safety case about her (category identity_mismatch): the booking is cancelled without a
-- refund, the account is suspended, and she can appeal under "Decisions about you"; an upheld appeal refunds the fee.
-- A mismatch also gets a second opinion from Gemini when GEMINI_API_KEY is set (lib/ai.js).
-- Needs 014 first. Re-running this file is safe.
SET search_path = app, pg_temp;

ALTER TABLE payments ADD COLUMN IF NOT EXISTS cardholder_name_enc bytea;
ALTER TABLE payments ADD COLUMN IF NOT EXISTS name_check varchar(12)
  CHECK (name_check IS NULL OR name_check IN ('match','mismatch','no_name','not_provided'));

CREATE TABLE IF NOT EXISTS identity_reviews (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  booking_id  uuid NOT NULL UNIQUE REFERENCES bookings(id),
  payment_id  uuid NOT NULL REFERENCES payments(id),
  user_id     uuid NOT NULL REFERENCES users(id),
  result      varchar(12) NOT NULL CHECK (result IN ('mismatch','no_name')),
  status      varchar(10) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')),
  decided_by  uuid REFERENCES admin_users(id),
  decided_at  timestamptz,
  report_id   uuid REFERENCES safety_reports(id),
  -- Gemini's second opinion on a mismatch (lib/ai.js): same first name? the card name's usual gender; confidence.
  -- It can only clear a false alarm (decided_by_ai) or raise priority; a rejection is always a person's decision.
  ai_same_name   boolean,
  ai_card_gender varchar(8) CHECK (ai_card_gender IS NULL OR ai_card_gender IN ('female','male','unclear')),
  ai_confidence  numeric(3,2),
  ai_checked_at  timestamptz,
  decided_by_ai  boolean NOT NULL DEFAULT false,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT identity_review_decided CHECK (status = 'pending' OR (decided_at IS NOT NULL AND (decided_by IS NOT NULL OR (decided_by_ai AND status = 'approved'))))
);
CREATE INDEX IF NOT EXISTS identity_reviews_pending ON identity_reviews (created_at) WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS identity_reviews_user_id_fk_idx ON identity_reviews (user_id);
