-- ==================== questionnaire QA-2026-04 (draft)
-- Questionnaire QA-2026-04 for HerZone: QA-2026-03 without Q08 (contact preference after the meetup). Contact is now
-- a request sent after the meetup (migration 010), open to every member, so the preference is no longer asked.
-- Same keys and option keys as v3, so submitted answers are offered again by key. Staging content: retires the
-- published version and publishes v4 (approved by the seeded owner). Re-running is a no-op.
SET search_path = app, pg_temp;

DO $$
DECLARE v uuid := '00000000-0000-0000-0000-0000000000eb';
BEGIN
  IF EXISTS (SELECT 1 FROM questionnaire_versions WHERE code = 'QA-2026-04') THEN RETURN; END IF;
